import re

_TITLE_RE = re.compile(
    r"<title(?:\s[^>]*)?>(.*?)</title\s*>",
    re.IGNORECASE | re.DOTALL,
)


def title_of(html: str) -> str:
    """Return the text between <title> and </title> in html, or "".

    Tag names match case-insensitively, and the opening tag may carry
    attributes. Only the first title element is used. Returns "" when
    there is no complete title element. Works on the given string only
    and does no network access.
    """
    m = _TITLE_RE.search(html)
    return m.group(1) if m else ""


def test_basic() -> None:
    assert title_of("<html><head><title>Hello</title></head></html>") == "Hello"


def test_no_title() -> None:
    assert title_of("<html><body>No title here</body></html>") == ""


def test_empty_input() -> None:
    assert title_of("") == ""


def test_empty_title() -> None:
    assert title_of("<title></title>") == ""


def test_case_insensitive() -> None:
    assert title_of("<HTML><TITLE>Upper</TITLE></HTML>") == "Upper"
    assert title_of("<Title>Mixed</tItLe>") == "Mixed"


def test_attributes_on_open_tag() -> None:
    assert title_of('<title id="t" lang="en">With attrs</title>') == "With attrs"


def test_first_title_wins() -> None:
    assert title_of("<title>One</title><title>Two</title>") == "One"


def test_unclosed_title() -> None:
    assert title_of("<title>Never closed") == ""


def test_missing_open_tag() -> None:
    assert title_of("Just text</title>") == ""


def test_multiline_title() -> None:
    assert title_of("<title>\n  Line one\n  Line two\n</title>") == "\n  Line one\n  Line two\n"


def test_whitespace_preserved() -> None:
    assert title_of("<title>  padded  </title>") == "  padded  "


def test_does_not_match_titlecase_tag_names() -> None:
    assert title_of("<titlebar>x</titlebar>") == ""


def test_svg_style_title_text_with_entities_untouched() -> None:
    assert title_of("<title>A &amp; B</title>") == "A &amp; B"

